    /// <summary>
    /// Generate pricing rule from a pre-defined pricing attribute group; the condition value is defaulted by default value of <c>IPricingAttribute</c>.
    /// </summary>
    /// <param name = "_priceAttrGroup">The price attribute group.</param>
    /// <returns>Generated pricing rule.</returns>
    public GUPPricingRule initPricingRule(GUPPricingAttributeGroup _priceAttrGroup)
    {
        GUPPricingRuleCondition ruleCondition;
        GUPPricingAttributeLink attrLink;

        if (!this.RecId)
        {
            throw error("@GlobalUnifiedPricing:GUPPricingRule_InsertFirst");
        }

        select firstonly ruleCondition where ruleCondition.RuleId == this.RecId;
        if (ruleCondition)
        {
            throw error(strFmt("@GlobalUnifiedPricing:GUPPricingRule_ConditionsExist", this.RecId));
        }

        ruleCondition.selectForUpdate(true);

        while select attrLink where attrLink.PriceAttributeGroup == _priceAttrGroup.RecId
        {
            ruleCondition.clear();
            ruleCondition.RuleId = this.RecId;
            ruleCondition.ConditionAttribute = attrLink.RecId;
            ruleCondition.ConditionValue = attrLink.DefaultValue;
            ruleCondition.insert();
        }

        this.PriceAttributeGroup = _priceAttrGroup.RecId;

        switch (this.getSourceLevel())
        {
            case GUPPricingAttributeSourceLevel::Header:
                this.ExclusionType = GUPPricingRuleExclusionType::Customer;
                break;
            case GUPPricingAttributeSourceLevel::Line:
                if (this.ExclusionType != GUPPricingRuleExclusionType::ProductVariant)
                {
                    this.ExclusionType = GUPPricingRuleExclusionType::Product;
                }
                break;
        }

        this.selectForUpdate(true);
        this.update();

        return this;
    }

    /// <summary>
    /// Determine if pricing object matches current pricing rule.
    /// </summary>
    /// <param name = "_pricingObject">The pricing object.</param>
    /// <returns>True if pricing object matches current pricing rule.</returns>
    public boolean match(Common _pricingObject)
    {
        GUPPricingRuleCondition ruleCondition;

        while select ruleCondition
            where ruleCondition.RuleId == this.RecId
        {
            if (!ruleCondition.match(_pricingObject))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Clear all child rule conditions and exclusions.
    /// </summary>
    public void clearRuleConditions()
    {
        if (this.RecId)
        {
            GUPPricingRuleCondition ruleCondition;
            GUPPricingRuleExclusion ruleExclusion;

            delete_from ruleCondition where ruleCondition.RuleId == this.RecId;
            delete_from ruleExclusion where ruleExclusion.RuleId == this.RecId;
        }
    }

    /// <summary>
    /// Clear all child rule exclusions.
    /// </summary>
    public void clearRuleExclusions()
    {
        if (this.RecId)
        {
            GUPPricingRuleExclusion ruleExclusion;

            delete_from ruleExclusion where ruleExclusion.RuleId == this.RecId;
        }
    }

    /// <summary>
    /// Exclude a customer account or an item id.
    /// </summary>
    /// <param name = "_exclusion">Exclusion value.</param>
    public void exclude(str _exclusion)
    {
        if (!this.RecId)
        {
            throw error("@GlobalUnifiedPricing:GUPPricingRule_InsertFirst");
        }

        GUPPricingRuleExclusion ruleExclusion;

        if (!this.isExcluded(_exclusion))
        {
            ruleExclusion.RuleId = this.RecId;
            ruleExclusion.Exclusion = _exclusion;
            ruleExclusion.insert();
        }
    }

    public void include(str _exclusion)
    {
        if (!this.RecId)
        {
            throw error("@GlobalUnifiedPricing:GUPPricingRule_InsertFirst");
        }

        GUPPricingRuleExclusion ruleExclusion;

        select firstonly ruleExclusion where ruleExclusion.RuleId == this.RecId && ruleExclusion.Exclusion == _exclusion;
        
        if (ruleExclusion)
        {
            ruleExclusion.selectForUpdate(true);
            ruleExclusion.delete();
        }
    }

    public boolean isExcluded(str _exclusion)
    {
        GUPPricingRuleExclusion ruleExclusion;

        select firstonly RecId from ruleExclusion where ruleExclusion.RuleId == this.RecId && ruleExclusion.Exclusion == _exclusion;

        return ruleExclusion.RecId;
    }

public display GUPPricingAttributeGroupNameHeader displayPricingAttributeGroupName()
{
    return this.pricingAttributeGroup().Name;
}

public display GUPPricingAttributeDetails displayPricingAttributeDetails()
{
    return this.displayPricingAttributeDetailsInPreview();
}

public display GUPPricingAttributeDetailsMemo displayPricingAttributeDetailsMemo()
{
    return this.displayPricingAttributeDetailsInPreview();
}

    public display GUPPricingAttributeDetailsPreview displayPricingAttributeDetailsInPreview()
    {   
        if (!this.PriceAttributeGroup)
        {
            return '';
        }

        GUPPricingAttributeDetailsPreview displayDetails = '';
        str attributeDetail;
        GUPPricingRuleCondition ruleCond;
        while select ruleCond where ruleCond.RuleId == this.RecId
        {
            str conditionValue = GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                                                                                ruleCond.pricingAttribute().getName(),
                                                                                ruleCond.ConditionValue,
                                                                                ruleCond.priceAttributeLink());
            attributeDetail = strFmt(
                '%1: %2; ',
                ruleCond.pricingAttribute().getName(),
                conditionValue);
            displayDetails += attributeDetail;
        }

        return displayDetails;
    }

    public display GUPPriceAttributeGroupPriority displayLinePriceAttributeGroupPriority()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection priceAttributeGroupSelection;

        select firstonly Priority from priceAttributeGroupSelection
            where priceAttributeGroupSelection.PriceAttributeGroup == this.PriceAttributeGroup;

        return priceAttributeGroupSelection.Priority;
    }

    internal GUPPricingAttributeGroup pricingAttributeGroup(boolean _selectForUpdate = false)
    {
        GUPPricingAttributeGroup pricingAttributeGroup;

        select firstonly pricingAttributeGroup where pricingAttributeGroup.RecId == this.PriceAttributeGroup;

        pricingAttributeGroup.selectForUpdate(_selectForUpdate);
        return pricingAttributeGroup;
    }

public void insert()
{   
    super();
}

    public static GUPPricingRule find(RefRecId _recId, boolean _selectForUpdate = false)
    {
        GUPPricingRule pricingRule;

        select firstonly pricingRule where pricingRule.RecId == _recId;
        pricingRule.selectForUpdate(_selectForUpdate);

        return pricingRule;
    }

    public boolean rangeOverlap(GUPPricingRule _otherRule, boolean _considerExclusion = false)
    {
        if (!_otherRule.RecId)
        {
            return false;
        }

        GUPPricingAttributeLink attrLink;
        GUPPricingRuleCondition ruleCondition, otherCondition;

        while select ruleCondition where ruleCondition.RuleId == this.RecId
        {
            attrLink = ruleCondition.priceAttributeLink();
            select firstonly otherCondition
                where otherCondition.RuleId == _otherRule.RecId
                && otherCondition.ConditionAttribute == attrLink.RecId;

            if (otherCondition && otherCondition.ConditionValue == ruleCondition.ConditionValue)
            {
                continue;
            }
            else
            {
                return false;
            }
        }

        // TODO: consider exclusion.

        return true;
    }

public GUPPricingAttributeSourceLevel getSourceLevel()
{
    return this.pricingAttributeGroup().SourceLevel;
}

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(GUPPricingRule, PriceAttributeGroup):
                this.initPricingRule(GUPPricingAttributeGroup::find(this.PriceAttributeGroup));
                break;
        }
    }

    internal GUPPricingRule copy()
    {
        GUPPricingRule          gupPricingRuleNew;
        GUPPricingRuleExclusion gupPricingRuleExclusion;
        GUPPricingRuleCondition gupPricingRuleCondition;
        GUPPricingRuleCondition gupPricingRuleConditionNew;

        if (this.RecId)
        {
            gupPricingRuleNew.clear();
            gupPricingRuleNew.data(this);
            gupPricingRuleNew.insert();

            //exclude
            while select gupPricingRuleExclusion
                where gupPricingRuleExclusion.RuleId == this.RecId
            {
                gupPricingRuleNew.exclude(gupPricingRuleExclusion.Exclusion);
            }

            //condition
            while select gupPricingRuleCondition
                where gupPricingRuleCondition.RuleId == this.RecId
            {
                gupPricingRuleConditionNew.clear();
                gupPricingRuleConditionNew.initFromGUPPricingRuleCondition(gupPricingRuleCondition);
                gupPricingRuleConditionNew.RuleId = gupPricingRuleNew.RecId;
                gupPricingRuleConditionNew.insert();
            }
        }

        return gupPricingRuleNew;
    }

    /// <summary>
    /// Create new pricing rule to use further for master records
    /// </summary>
    /// <param name = "_pricingGroup">Pricing group. Can be 0</param>
    /// <returns>Pricing rule</returns>
    public static GUPPricingRule createRule(GUPPricingAttributeGroupRecId _pricingGroup = 0)
    {
        GUPPricingRule pricingRule;

        ttsbegin;

        pricingRule.PriceAttributeGroup = _pricingGroup;
        pricingRule.insert();

        if (pricingRule.PriceAttributeGroup)
        {
            pricingRule.initPricingRule(GUPPricingAttributeGroup::find(pricingRule.PriceAttributeGroup));
        }

        ttscommit;

        return pricingRule;
    }

    /// <summary>
    /// Set pricing group to empty and clear related conditions
    /// </summary>
    public void clearPricingGroup()
    {
        ttsbegin;

        this.selectForUpdate(true);

        this.PriceAttributeGroup = 0;
        this.update();

        this.clearRuleConditions();
        GUPPricingAttributeLineState::clearLineState(this.TableId, this.RecId);
        ttscommit;
    }

/// <summary>
/// Include or exclude line related to current pricing rule
/// </summary>
/// <param name = "_lineType">Action to perform - include or exclude</param>
/// <param name = "_refTableId">Reference table Id of line to be included/excluded</param>
/// <param name = "_refRecId">Reference record Id of line to be included/excluded</param>
public void inclExclRelLine(GUPPricingAttributeLineType _lineType, RefTableId _refTableId, RefRecId _refRecId)
{
    if (_lineType == GUPPricingAttributeLineType::Exclude)
    {
        GUPPricingAttributeLineState::excludeLine(this.TableId, this.RecId, _refTableId, _refRecId);
    }
    else
    {
        GUPPricingAttributeLineState::includeLine(this.TableId, this.RecId, _refTableId, _refRecId);
    }
}

/// <summary>
/// insert new pricing rule
/// </summary>
/// <param name = "_attributeGroup">Pricing attribute group</param>
/// <param name = "_exclusionType">Exclusion type</param>
/// <returns>Generated pricing rule.</returns>
public static GUPPricingRule newPricingRule(GUPPricingAttributeGroupRecId _attributeGroup, GUPPricingRuleExclusionType _exclusionType)
{
    GUPPricingRule rule;
    rule.PriceAttributeGroup = _attributeGroup;
    rule.ExclusionType = _exclusionType;
    rule.insert();
    return rule;
}

    /// <summary>
    /// Update pricing attribute group on pricing rule; clear conditions and line state
    /// </summary>
    /// <param name = "_pricingRuleRecId">Pricing rule to update</param>
    /// <param name = "_priceAttributeGroupRecId">Pricing attribute group</param>
    public static void updatePriceAttributeGroup(GUPPricingRuleRecId _pricingRuleRecId, GUPPricingAttributeGroupRecId _priceAttributeGroupRecId)
    {
        GUPPricingRule pricingRule;

        if (_pricingRuleRecId)
        {
            ttsbegin;

            pricingRule = GUPPricingRule::find(_pricingRuleRecId, true);

            if (pricingRule.PriceAttributeGroup != _priceAttributeGroupRecId)
            {
                pricingRule.clearRuleConditions();
                GUPPricingAttributeLineState::clearLineState(pricingRule.TableId, pricingRule.RecId);

                pricingRule.PriceAttributeGroup = _priceAttributeGroupRecId;
                pricingRule.modifiedField(fieldNum(GUPPricingRule, PriceAttributeGroup));
                pricingRule.update();
            }

            ttscommit;
        }
    }

